import { scaleLinear } from '@visx/scale';

import { getMinMax } from './get-min-max.js';
import { AxisIdToScaleMap } from '../context/XYChartXScalesContext.js';
import {
  AxisId,
  XYChartAxisProps,
  XYChartData,
  XYChartScale,
  XYChartVariants,
} from '../types/xy-chart.js';

export function generateScalesByXAxisId(
  axes: XYChartAxisProps[],
  seriesVariantProps: XYChartVariants[],
  data: XYChartData[],
  width: number,
): AxisIdToScaleMap {
  const map = new Map<AxisId, XYChartScale>();
  const flatSeries = seriesVariantProps.flat();

  axes.forEach((axis) => {
    const series = flatSeries.filter((series) => axis.id === series.xAxisId);

    const { minMaxX } = getMinMax([series], data);

    const scale = scaleLinear({
      domain: [minMaxX.min, minMaxX.max],
      range: [0, width],
    });

    map.set(axis.id, scale);
  });

  return map;
}
